 async function save(){if(saveLock.current)return;if(!ready){setNotice('Kayıt güvenliği nedeniyle ekleme kapalı. Sayfayı yenile veya yedek içe aktar.');return}if(!draft.word.trim()||!draft.meaning.trim()||draft.selectionRequired)return;const duplicate=findDuplicateCard(cards,draft,edit);if(duplicate){setDuplicateId(duplicate.id);setModalMessage('Bu kelime zaten kayıtlı. Tekrar geçmişin değiştirilmedi.');return;}const old=cards.find(c=>c.id===edit);const resolvedRection=resolveRection(draft.word.trim(),draft.rection);const c:Card={...old,id:edit||crypto.randomUUID(),informationCheckedAt:draft.informationCheckedAt||old?.informationCheckedAt,partOfSpeech:draft.partOfSpeech||undefined,articleAmbiguous:!!draft.articleAmbiguous,inflections:safeInflections(draft.inflections),rection:safeRection(resolvedRection),word:draft.word.trim(),article:draft.article,plural:draft.plural,meaning:draft.meaning.trim(),example:draft.example,translation:draft.translation,photo,source:draft.source,note:draft.note||'Anlam ve örneği kontrol ederek kaydedildi.',due:old?.due||0,interval:old?.interval||0,reviews:old?.reviews||0,created:old?.created||Date.now()};saveLock.current=true;setSaving(true);setModalMessage('');try{if(!repository.current)throw Error('Yerel kayıt hazır değil.');const committed=await repository.current.update(prev=>{const duplicate=findDuplicateCard(prev,c,edit);if(duplicate)throw new DuplicateCardError(duplicate);return edit?prev.map(p=>p.id===edit?c:p):[c,...prev];});setCardsState(committed.map(c=>({...c,rection:resolveRection(c.word,c.rection)})));setModal(false);setQuery('');setNotice(edit?'Kelime güncellendi.':'Yeni kelimen bahçene eklendi.');}catch(e){if(e instanceof DuplicateCardError){setDuplicateId(e.card.id||'');setModalMessage(e.message+' Tekrar geçmişin değiştirilmedi.');}else setModalMessage(cardStorageError(e));}finally{saveLock.current=false;setSaving(false);}}
 async function updateDuplicate(){if(saveLock.current||!duplicateId)return;saveLock.current=true;setSaving(true);try{const saved=await setCards(prev=>prev.map(c=>c.id===duplicateId?fillMissingCardFields(c,{...draft,photo}):c));if(!saved)setModalMessage('Eksik bilgiler kaydedilemedi. Eski kartın ve tekrar geçmişin korunuyor; tekrar dene.');if(saved){setModalMessage('Yalnız boş alanlar tamamlandı. Mevcut anlam, not ve tekrar geçmişi korundu.');}}finally{saveLock.current=false;setSaving(false);}}
 /** Looks a saved card up (no write yet). Results are applied in batches: one storage write per batch, not per card. */
 async function fetchLookup(c:Card){
  try{
   const r=await fetch('/api/lookup?word='+encodeURIComponent(c.word)+'&exact=1');const d:any=await r.json();
   if(!r.ok||d.selectionRequired||d.word!==c.word)return null;
   return{id:c.id,word:c.word,data:d,forms:safeInflections(d.inflections) as Card['inflections'],rection:safeRection(d.rection) as Card['rection'],photo:d.images?.find((p:Photo)=>p.match==='curated')};
  }catch{return null;}
 }
 type LookupResult=NonNullable<Awaited<ReturnType<typeof fetchLookup>>>;
