 async function enrichOne(c:Card):Promise<'saved'|'skipped'|'failed'>{const r=await fetchLookup(c);if(!r)return 'skipped';return (await applyBatch([r]))?'saved':'failed';}
 async function enrichMissing(){if(enriching||!ready)return;cancelEnrich.current=false;setEnriching(true);const targets=cards.filter(c=>!c.informationCheckedAt||((!c.inflections||!c.rection)&&c.informationCheckedAt<Date.now()-7*86400000)).sort((a,b)=>(a.informationCheckedAt||0)-(b.informationCheckedAt||0)).slice(0,40);let updated=0;let batch:LookupResult[]=[];for(const c of targets){if(cancelEnrich.current)break;setNotice(`${updated+batch.length}/${targets.length} kart araştırıldı. Mevcut anlamın ve tekrar geçmişin korunuyor.`);const r=await fetchLookup(c);if(r)batch.push(r);if(batch.length>=10){if(!(await applyBatch(batch))){cancelEnrich.current=true;setEnriching(false);return}updated+=batch.length;batch=[];}}if(batch.length&&await applyBatch(batch))updated+=batch.length;setEnriching(false);setNotice(`${updated} kartın kontrolü kaydedildi. Kaynakta eksik olan bilgi tahmin edilmedi; mevcut alanlar ve tekrar geçmişi korundu.`)}
 function editCard(c:Card){setEdit(c.id);setEditorOpen(false);setPreview({...blank(),...c,rection:resolveRection(c.word,c.rection),images:c.photo?[c.photo]:[]},c.photo);setModal(true)}
 function openRectionCard(r:RectionData){const existing=cards.find(c=>c.word.toLocaleLowerCase('de')===r.lemma.toLocaleLowerCase('de'));if(existing){editCard(existing);return;}const first=r.patterns[0];const ex=first?first.example.parts.map(p=>p.text).join(''):'';setEdit('');setPhoto(undefined);setDraft({...blank(),word:r.lemma,partOfSpeech:'verb',meaning:first?`${first.explanation} (${first.pattern})`:'',example:ex,translation:first?.example.translation||'',rection:r,source:first?.sources?.[0]?.url||''});setModal(true);}
 async function rate(r:0|1|2|3){if(!current||saving||reviewLock.current)return;reviewLock.current=true;revealReady.current=false;setSaving(true);try{const saved=await setCards(prev=>prev.map(c=>c.id===current.id?scheduleReview(c,r,prev):c));if(!saved){revealReady.current=true;return;}setQueue(q=>reviewAfterAnswer(q,r,reviewRecovery));if(r<=1&&!reviewRecovery.includes(current.id))setReviewRecovery(ids=>[...ids,current.id]);setReviewAttempts(n=>n+1);if(!reviewAnswered.includes(current.id)){setDone(n=>n+1);setReviewAnswered(ids=>[...ids,current.id]);}setReveal(false);setMixedReverse(Math.random()<.5);}finally{reviewLock.current=false;setSaving(false);}}
