 useEffect(()=>{if(page!=='review'||modal||flagId||importPreview||!current)return;const listener=(event:KeyboardEvent)=>{const target=event.target as HTMLElement|null;const editing=!!target?.closest('input,textarea,select,[contenteditable="true"],[contenteditable=""]');const action=reviewShortcut(event,revealReady.current,editing);if(action===null||reviewLock.current||saving)return;event.preventDefault();if(action==='reveal'){revealReady.current=true;setReveal(true);}else{revealReady.current=false;void rate(action);}};window.addEventListener('keydown',listener);return()=>window.removeEventListener('keydown',listener);},[page,modal,flagId,importPreview,current?.id,reveal,saving,reviewRecovery,reviewAnswered,cards]);
 function openFlag(id:string){const c=cards.find(c=>c.id===id);if(!c)return;setFlagId(id);setFlagNote(c.qualityFlag?.note||'');setFlagError('');}
