 async function backup(){
  if(!repository.current||!ready)return false;
  try{
   const savedCards=await repository.current.refresh();
   const extraLearning=await exportExtendedLearning(true);
   const data={version:2,exportedAt:new Date().toISOString(),cards:savedCards,learningProgress:exportLearning(localStorage),extraLearning};
   const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));
   const link=document.createElement('a');
   link.href=url;link.download='wortgarten-kelime-yedegi.json';
   document.body.append(link);link.click();link.remove();
   window.setTimeout(()=>URL.revokeObjectURL(url),30000);
   return true;
  }catch{
   setNotice('Yedek hazırlanamadı. Kayıtlar korunuyor. Sayfayı yeniden açıp tekrar dene.');
   return false;
  }
 }
 async function restore(file?:File){if(!file)return;try{if(!ready)throw Error('Önce bilgisayar kaydının yüklenmesini bekle.');if(file.size>50000000)throw Error('Yedek 50 MB sınırını aşıyor.');const parsed=parseCardBackup(JSON.parse(await file.text()));setImportPreview({backup:parsed,before:cards});}catch(e){setNotice(e instanceof Error?e.message:'Yedek okunamadı.');}}
 async function applyImport(choices:ImportChoices){if(!importPreview||!repository.current)throw Error('Aktarım hazır değil.');const source=importPreview;const originalFingerprint=backupCardsFingerprint(source.before);const result=applyCardImport(source.before,source.backup.cards,choices);prepareExtendedLearningImport(source.backup.extraLearning,result.idMap);const extraBefore=await exportExtendedLearning(true);const rawLearning=Object.fromEntries(LEARNING_KEYS.map(key=>[key,localStorage.getItem(key)]));await writeLearningValue('wortgarten-import-recovery-v1',{version:1,createdAt:Date.now(),before:{cards:source.before,rawLearning,extraLearning:extraBefore},incoming:source.backup.raw,choices});const committed=await repository.current.update(prev=>{if(backupCardsFingerprint(prev.map(c=>({...c,rection:resolveRection(c.word,c.rection)})))!==originalFingerprint)throw Error('Bilgisayar kartları önizlemeden sonra değişti. Dosyayı yeniden seç; mevcut kayıt korundu.');return result.cards;});setCardsState(committed.map(c=>({...c,rection:resolveRection(c.word,c.rection)})));try{restoreLearning(localStorage,source.backup.learningProgress,result.idMap,choices.skills);await restoreExtendedLearning(source.backup.extraLearning,choices.skills,result.idMap);}catch{setImportPreview(null);setNotice('Kartlar birleştirildi; ancak beceri aktarımı eksik kaldı. Tam eşitleme tamamlanmadı. İki ham yedeği sakla; işlem öncesi kurtarma kopyası bu cihazda korunuyor.');return 'partial';}window.dispatchEvent(new Event('wortgarten-learning-changed'));setImportPreview(null);setNotice(`Aktarım tamam: ${result.added} yeni, ${result.matched} eşleşen; toplam ${committed.length} kart. Ham yedeklerini sakla.`);return 'complete';}

