 const qDe=search.toLocaleLowerCase('de'),qTr=search.toLocaleLowerCase('tr');
 const filteredCards=cards.filter(c=>{if(!matchesFilter(c))return false;const r=resolveRection(c.word,c.rection);const de=(c.word+' '+(r.status==='known'?r.patterns.map(p=>p.pattern).join(' '):'')).toLocaleLowerCase('de');const tr=c.meaning.toLocaleLowerCase('tr');return de.includes(qDe)||tr.includes(qTr);});const library=libraryPage(filteredCards,libraryIndex);
