 const addQuickEntry=async(entry:any)=>{setSaving(true);try{const c:Card={...entry,id:crypto.randomUUID(),due:0,interval:0,reviews:0,created:Date.now(),note:'Hızlı kelime ekleme · sözlük karşılığı.',rection:resolveRection(entry.word)};let duplicate=false;const ok=await setCards(prev=>{if(findDuplicateCard(prev,c)){duplicate=true;return prev}return[c,...prev]});if(ok&&duplicate)setNotice('Bu kelime zaten kayıtlı. Tekrar geçmişi korundu.');if(ok&&!duplicate)queueEnrich([c]);return ok}finally{setSaving(false)}};
 /** One background worker completes saved words one at a time (about 26 lookups a minute); results are written 25 at a time, never one by one. */
 const enrichQueue=useRef<Card[]>([]);const enrichRunning=useRef(false);
 function queueEnrich(list:Card[]){enrichQueue.current.push(...list);if(enrichRunning.current)return;enrichRunning.current=true;void (async()=>{let batch:LookupResult[]=[];try{for(let c=enrichQueue.current.shift();c;c=enrichQueue.current.shift()){const r=await fetchLookup(c);if(r)batch.push(r);if(batch.length>=25){await applyBatch(batch);batch=[];}await new Promise(res=>setTimeout(res,2300));}}finally{if(batch.length)await applyBatch(batch);enrichRunning.current=false;}})();}
 /** Completes pack cards from the precomputed pack data (tables, case notes, plural, picture, example sentences with credit): one fetch and one storage write per pack, no per-word lookups. */
 async function mergePackData(installed?:string[]){
  let activeInstalled:string[]=installed??[];
  if(!installed){try{activeInstalled=parseInstalled(localStorage.getItem(PACKS_KEY));}catch{/* private mode */}}
  let done:string[]=[];try{done=parseInstalled(localStorage.getItem(PACK_DATA_KEY));}catch{/* private mode */}
  for(const pack of WORD_PACKS){
   if(!activeInstalled.includes(pack.id)||done.includes(pack.id))continue;
   const data=await loadPackData(pack.id);if(!data)continue;
   const prefix='pack-'+pack.id+'-';
   const ok=await setCards(prev=>applyLookups(prev,prev.filter(c=>c.id.startsWith(prefix)&&!c.informationCheckedAt).flatMap(c=>{const e=data[c.word];return e?[{id:c.id,word:c.word,...lookupFromEntry(e)} as any]:[];})));
   if(!ok)break;
   primeExamples(exampleEntries(data));
   done=[...done,pack.id];try{localStorage.setItem(PACK_DATA_KEY,JSON.stringify(done));}catch{/* private mode */}
  }
 }
 /** Adds a ready-made word pack (skipping words already saved), then completes forms, case notes and pictures in the background, one word at a time. */
 const addPack=async(pack:WordPack)=>{setSaving(true);let fresh:Card[]=[];try{const now=Date.now();const ok=await setCards(prev=>{const known=new Set(prev.map(c=>basicWordKey(c.word)));fresh=pack.words.filter(e=>!known.has(basicWordKey(e.word))).map((e,i):Card=>({...e,note:pack.note,id:'pack-'+pack.id+'-'+basicWordKey(e.word),due:0,interval:0,reviews:0,created:now-i,rection:resolveRection(e.word)}));return fresh.length?[...fresh,...prev]:prev});if(!ok)throw Error('Kayıt başarısız');return fresh.length}finally{setSaving(false);}};
 const addBasicWords=async()=>{setSaving(true);try{let added=0;const now=Date.now();const ok=await setCards(prev=>{const known=new Set(prev.map(c=>basicWordKey(c.word)));const fresh=BASIC_WORDS.filter(entry=>!known.has(basicWordKey(entry.word))).map((entry,i):Card=>({...entry,id:'basic-v1-'+basicWordKey(entry.word),due:0,interval:0,reviews:0,created:now-i,rection:resolveRection(entry.word)}));added=fresh.length;return fresh.length?[...fresh,...prev]:prev});if(!ok)throw Error('Kayıt başarısız');return added}finally{setSaving(false)}};
