 {page==='quality'&&<><div className="heading-row"><div><h1>Kontrol bekleyenler</h1><p className="lead">Not bıraktığın kelimeler: bütün bilgiler ve kayıtlı fotoğraf kontrol kapsamındadır.</p></div></div><p className="micro">Bu bir kontrol kuyruğudur. Otomatik yapay zekâ incelemesi henüz çalışmaz; bilgiler kendiliğinden değiştirilmez.</p>{cards.filter(c=>c.qualityFlag?.status==='pending').map(c=><article className="quality-card" key={c.id}><h2>{c.word}</h2><p>{c.qualityFlag?.note||'Bütün bilgileri ve fotoğrafı kontrol et.'}</p><small>{new Date(c.qualityFlag!.createdAt).toLocaleString('tr-TR')} · Kontrol bekliyor</small><button className="secondary" onClick={()=>editCard(c)}>Bütün bilgileri aç</button><button className="text-button" onClick={()=>openFlag(c.id)}>Notu düzenle</button><button className="text-button" disabled={flagBusy} onClick={()=>void clearFlag(c.id)}>Kontrol tamamlandı · işareti kaldır</button>{c.photo&&<img src={c.photo.url} alt={c.word+' kayıtlı fotoğrafı'} width={240} height={150} loading="lazy"/>}</article>)}{!cards.some(c=>c.qualityFlag)&&<p>Henüz işaretlenmiş kelime yok.</p>}</>}

