 {modal&&<ModalShell labelledBy="modal-title" closeDisabled={busy||saving} onClose={closeModal}>{discardPrompt&&<div className="discard-prompt" role="alert"><p>Kaydedilmemiş değişikliklerden vazgeçmek istiyor musun?</p><button className="secondary" onClick={()=>setDiscardPrompt(false)}>Düzenlemeye devam et</button><button className="secondary" onClick={()=>{setDiscardPrompt(false);setModal(false)}}>Değişiklikleri at</button></div>}<div className="modal-heading"><div><h2 id="modal-title">{edit?'Kelime ayrıntısı':'Kelime sonucu'}</h2></div><button className="primary modal-save" onClick={save} disabled={busy||saving||!draft.word.trim()||!draft.meaning.trim()||draft.selectionRequired||!ready}><Plus size={16}/>{saving?'Cihaza kaydediliyor…':edit?'Değişiklikleri kaydet':'Kelimeyi ekle'}</button><button className="icon-btn" aria-label="Pencereyi kapat" disabled={busy||saving} onClick={closeModal}><X/></button></div>{modalMessage&&<section className="article-method" role="alert"><p>{modalMessage}</p>{duplicateId&&<div className="journey-actions"><button className="secondary" disabled={saving} onClick={()=>{const old=cards.find(c=>c.id===duplicateId);if(old){editCard(old);setDuplicateId('');setModalMessage('Mevcut kart açıldı.');}}}>Mevcut kartı aç</button><button className="secondary" disabled={saving} onClick={()=>void updateDuplicate()}>Yalnız eksik bilgileri tamamla</button></div>}</section>}{!busy&&editorOpen&&(!draft.word.trim()||!draft.meaning.trim())&&<p className="micro modal-validation" role="status">Kaydetmek için kelimeyi ve Türkçe anlamını doldur.</p>}{busy?<div className="lookup-loading"><Leaf className="spin" size={34}/><h3>Kelime bilgileri yükleniyor…</h3><button type="button" className="secondary" onClick={cancelLookup}>Aramayı durdur</button><p>Sözlük, Türkçe anlam ve görsel kaynakları taranıyor.</p></div>:<>{draft.rootChoices?.length>1&&<div className="root-choices"><p>Hangi anlamı veya temel kelimeyi kastediyorsun?</p><p className="micro">Aynı kelime + artikel + sözcük türü için şu an tek kart tutulur. Kelime zaten kayıtlıysa mevcut kartın anlamını düzenle; bu seçim eski kartının üzerine otomatik yazmaz.</p>{draft.rootChoices.map((c:any)=><button className="secondary" key={c.senseId||c.word} onClick={()=>lookup(c.lookupWord||c.word,!!edit,c.senseId)}>{c.label||((c.article?c.article+' ':'')+c.word)}<small>{c.meaning}</small></button>)}</div>}<WordResult data={{...draft,rection:activeDraftRection}} compact collapseTables onSpeak={speak} media={<WordPhotos images={draft.images||[]} selected={photo} onSelect={setPhoto}/>}/>
 <details className="word-editor word-extra" open={editorOpen} onToggle={e=>setEditorOpen(e.currentTarget.open)}><summary>Bilgileri düzenle / eksik bilgi ekle</summary><div className="form-grid word-core"><label>Kelime *<input autoComplete="off" name="word" value={draft.word} maxLength={100} onChange={e=>setDraft({...draft,word:e.target.value,rection:resolveRection(e.target.value,draft.rection)})}/></label><label>Artikel<select value={draft.article} onChange={e=>setDraft({...draft,article:e.target.value})}><option value="">Yok / bilinmiyor</option><option>der</option><option>die</option><option>das</option></select></label>{draft.articleAmbiguous&&<label className="full ambiguous-article"><input type="checkbox" checked={false} onChange={()=>setDraft({...draft,articleAmbiguous:false})}/>Bu anlam için seçtiğim tekil artikeli doğruladım. (Doğrulanana kadar artikel pratiğine alınmaz.)</label>}<label className="full">Türkçe anlamı *<input autoComplete="off" name="meaning" value={draft.meaning} maxLength={1000} onChange={e=>setDraft({...draft,meaning:e.target.value})}/></label><label className="full">Çoğul (artikel olmadan)<input autoComplete="off" value={draft.plural} onChange={e=>setDraft({...draft,plural:e.target.value})}/></label></div><details className="word-extra"><summary>Örnek cümle ve kişisel not</summary><div className="form-grid"><label className="full">Almanca örnek cümle<textarea rows={2} value={draft.example} maxLength={2000} onChange={e=>setDraft({...draft,example:e.target.value})}/></label><label className="full">Örneğin Türkçe karşılığı <small>Kaynak veya makine çevirisi olabilir; seçtiğin anlamla karşılaştır.</small><textarea rows={2} maxLength={2000} value={draft.translation} onChange={e=>setDraft({...draft,translation:e.target.value})}/></label><label className="full">Kişisel not<textarea rows={2} value={draft.note||''} maxLength={4000} onChange={e=>setDraft({...draft,note:e.target.value})}/></label></div></details>{draft.inflections?.tables?.length>0&&<details className="form-corrections"><summary>Hücreleri elle düzelt</summary><p className="micro">Düzeltmelerin bu karta kaydedilir; kaynağı değiştirmez. Birden fazla biçimi noktalı virgülle ayır.</p>{draft.inflections.tables.map((t:any,ti:number)=><div key={ti}><h4>{t.title}</h4>{t.rows.map((r:any,ri:number)=><div className="correction-row" key={ri}><b>{r.label}</b>{r.cells.map((c:string[],ci:number)=><label key={ci}>{t.columns[ci]}<input autoComplete="off" value={c.join('; ')} maxLength={600} onChange={e=>changeForm(ti,ri,ci,e.target.value)}/></label>)}</div>)}</div>)}</details>}</details>

 {(draft.source||draft.warnings?.length>0)&&<details className="word-extra result-sources"><summary>Kaynak ve kontrol notları</summary>{draft.source&&<a href={draft.source} target="_blank" rel="noreferrer">Sözlük kaynağı</a>}{draft.warnings?.map((w:string)=><p className="micro" key={w}>{w}</p>)}</details>}
 <div className="modal-actions">{edit&&<button className="secondary" disabled={busy||saving} onClick={()=>openFlag(edit)}>Kontrol için not bırak</button>}<button className="secondary" disabled={busy||saving} onClick={closeModal}>Kaydetmeden çık</button><button className="text-button" disabled={busy||!draft.word.trim()||draft.selectionRequired} onClick={refreshForms}>Bilgileri ve görselleri yeniden araştır</button></div>
</>}</ModalShell>}
 {flagId&&<ModalShell labelledBy="flag-title" closeDisabled={flagBusy} onClose={()=>setFlagId('')}><h2 id="flag-title">Kontrol için not bırak</h2><p><b>{cards.find(c=>c.id===flagId)?.word}</b> · Tüm bilgiler ve kayıtlı fotoğraf incelenecekler listesine alınır.</p><label className="flag-note">Ne yanlış veya eksik görünüyor?<textarea maxLength={2000} rows={4} value={flagNote} onChange={e=>setFlagNote(e.target.value)} placeholder="Örn. fotoğraf anlamla ilgisiz; Dativ örneği yanlış…"/></label>{flagError&&<p role="alert">{flagError}</p>}<p className="micro">Yalnız not ve kontrol işareti kaydedilir. Otomatik inceleme veya düzeltme yapılmaz.</p><div className="modal-actions"><button className="primary" disabled={flagBusy} onClick={saveFlag}>{flagBusy?'Kaydediliyor…':'Kontrol kuyruğuna ekle'}</button>{cards.find(c=>c.id===flagId)?.qualityFlag&&<button className="secondary" disabled={flagBusy} onClick={()=>void clearFlag(flagId)}>Kontrol tamamlandı · işareti kaldır</button>}<button className="secondary" disabled={flagBusy} onClick={()=>setFlagId('')}>Vazgeç</button></div></ModalShell>}
